    RouteGroup("Alertas", "Funciones de Funnelchat", 8, "Ver las alertas que hay y los destinos de tus alertas, elegir qué alerta le llega a cada destino, y el horario de silencio y el reporte diario de tu cuenta."),
    RouteGroup("Webhooks", "Funciones de Funnelchat", 8, "Recibir en tu servidor lo que pasa en tu cuenta: crear, ver, editar, probar y borrar tus webhooks, sus entregas y los tipos de evento."),
